// EDIT: your business settings (used by every flow)
const cfg = {
  business_name: 'Bright Smile Dental',
  timezone: 'America/New_York',
  open_hour: 9,
  close_hour: 17,
  slot_minutes: 60,
  open_days: [1, 2, 3, 4, 5]   // 1 = Monday ... 7 = Sunday
};
return { json: { ...$json, cfg } };

const msg = $json.body.message || {};
const tc = (msg.toolCallList && msg.toolCallList[0]) || (msg.toolCalls && msg.toolCalls[0]) || {};
const fn = tc.function || {};
let args = fn.arguments || tc.arguments || {};
if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }
return { json: {
  toolCallId: tc.id || '',
  toolName: fn.name || tc.name || '',
  args,
  callId: (msg.call && msg.call.id) || '',
  callerNumber: (msg.call && msg.call.customer && msg.call.customer.number) || ''
} };

const cfg = $('Business Config').first().json.cfg;
const day = DateTime.fromISO(String($json.args.date || ''), { zone: cfg.timezone });
if (!day.isValid) {
  const n = DateTime.now().setZone(cfg.timezone);
  return { json: { ...$json, invalid: true, timeMin: n.toISO(), timeMax: n.plus({ hours: 1 }).toISO() } };
}
return { json: { ...$json, invalid: false, dayISO: day.toISODate(), timeMin: day.startOf('day').toISO(), timeMax: day.endOf('day').toISO() } };

const cfg = $('Business Config').first().json.cfg;
const ctx = $('Compute Day Range').first().json;
const out = (result) => [{ json: { toolCallId: ctx.toolCallId, toolName: ctx.toolName, result } }];
if (ctx.invalid) return out('I could not understand that date. Ask the caller for the date again.');
const zone = cfg.timezone;
const day = DateTime.fromISO(ctx.dayISO, { zone });
const label = day.toFormat('cccc, LLLL d');
if (!cfg.open_days.includes(day.weekday)) return out('We are closed on ' + label + '. Offer another day.');
const busy = items.map(i => i.json).filter(e => e && e.start).map(e => ({
  s: DateTime.fromISO(e.start.dateTime || e.start.date, { zone }),
  e: DateTime.fromISO(e.end.dateTime || e.end.date, { zone })
}));
const now = DateTime.now().setZone(zone);
const free = [];
for (let m = cfg.open_hour * 60; m + cfg.slot_minutes <= cfg.close_hour * 60; m += cfg.slot_minutes) {
  const s = day.set({ hour: Math.floor(m / 60), minute: m % 60, second: 0, millisecond: 0 });
  const e = s.plus({ minutes: cfg.slot_minutes });
  if (s < now) continue;
  if (busy.some(b => s < b.e && e > b.s)) continue;
  free.push(s.toFormat('h:mm a'));
}
return out(free.length ? 'Available times on ' + label + ': ' + free.join(', ') + '.' : 'There is no availability on ' + label + '. Offer another date.');

const cfg = $('Business Config').first().json.cfg;
const a = $json.args || {};
const zone = cfg.timezone;
const day = DateTime.fromISO(String(a.date || ''), { zone });
const raw = String(a.time || '').trim().toUpperCase();
let t = null;
for (const f of ['h:mm a', 'h a', 'h:mma', 'ha', 'H:mm', 'HH:mm']) {
  const x = DateTime.fromFormat(raw, f, { zone });
  if (x.isValid) { t = x; break; }
}
const start = (day.isValid && t) ? day.set({ hour: t.hour, minute: t.minute, second: 0, millisecond: 0 }) : null;
const spoken = String(a.phone || '').replace(/[^\d+]/g, '');
const phone = spoken.startsWith('+') ? spoken : ($json.callerNumber || spoken);
const customer_name = String(a.name || '').trim();
const service = String(a.service || 'Appointment').trim();
let error = '';
let end = null;
if (!customer_name) error = 'The caller name is missing. Ask for it.';
else if (!start) error = 'I could not understand the date or time. Ask the caller to repeat it.';
else {
  end = start.plus({ minutes: cfg.slot_minutes });
  const closeT = day.set({ hour: cfg.close_hour, minute: 0, second: 0, millisecond: 0 });
  if (!cfg.open_days.includes(start.weekday)) error = 'We are closed on that day. Offer another day.';
  else if (start < DateTime.now().setZone(zone)) error = 'That time has already passed. Ask for a future time.';
  else if (start.hour < cfg.open_hour || end > closeT) error = 'That time is outside opening hours. Offer a time between ' + cfg.open_hour + ':00 and ' + cfg.close_hour + ':00.';
}
return { json: {
  toolCallId: $json.toolCallId, toolName: $json.toolName, callId: $json.callId,
  valid: !error, error, customer_name, phone, service,
  startISO: start ? start.toISO() : '', endISO: end ? end.toISO() : '',
  whenLabel: start ? start.toFormat("cccc, LLLL d 'at' h:mm a") : '',
  booking_id: 'APT-' + Date.now().toString(36).toUpperCase()
} };

const ctx = $('Prepare Booking').first().json;
const events = items.map(i => i.json).filter(e => e && e.id);
// idempotency: if Vapi re-sends the same tool call, the event for this call already exists
const already = ctx.callId ? events.some(e => String(e.description || '').includes('call_id: ' + ctx.callId)) : false;
return [{ json: { ...ctx, slotFree: events.length === 0, alreadyBooked: already } }];

const c = $json;
const result = c.alreadyBooked
  ? 'This booking is already confirmed for ' + c.whenLabel + '. Confirm it to the caller.'
  : 'Sorry, ' + c.whenLabel + ' is no longer available. Offer to check other times.';
return { json: { toolCallId: c.toolCallId, toolName: c.toolName, result } };

