const ctx = $('Parse Tool Call').first().json;
const row = items.map(i => i.json).find(r => r && r.booking_id);
const action = String(ctx.args.action || '').toLowerCase();
return [{ json: { toolCallId: ctx.toolCallId, toolName: ctx.toolName, found: !!row, action, row: row || null } }];

const m = $json.body.message || {};
const call = m.call || {};
const art = m.artifact || {};
let dur = m.durationSeconds || (m.durationMs ? Math.round(m.durationMs / 1000) : 0);
const started = call.startedAt || m.startedAt;
const ended = call.endedAt || m.endedAt;
if (!dur && started && ended) dur = Math.round((new Date(ended) - new Date(started)) / 1000);
return { json: {
  call_id: call.id || '',
  time: new Date().toISOString(),
  phone: (call.customer && call.customer.number) || '',
  duration_sec: dur || 0,
  ended_reason: m.endedReason || call.endedReason || '',
  vapi_summary: m.summary || (m.analysis && m.analysis.summary) || '',
  transcript: String(art.transcript || m.transcript || '').slice(0, 8000),
  recording_url: art.recordingUrl || m.recordingUrl || ''
} };

messageValues.message:
You analyze phone call transcripts between a caller and an AI receptionist. Output ONLY valid JSON:
{"intent":"booking|question|complaint|cancellation|other","outcome":"booked|info_given|needs_followup|abandoned","sentiment":"positive|neutral|negative","urgent":false,"caller_name":"","summary":"max 25 words","follow_up":"what a human should do next, or empty string"}

Rules: use ONLY facts in the transcript. urgent = true only for emergencies, angry callers or explicit requests for a human. outcome = needs_followup if the caller asked for something the AI could not complete.

