const cfg = $('Business Config').first().json.cfg;
const tomorrow = DateTime.now().setZone(cfg.timezone).plus({ days: 1 }).toISODate();
const out = [];
for (const it of items) {
  const r = it.json;
  if (!r.booking_id || r.status !== 'booked' || String(r.reminded).toLowerCase() === 'yes') continue;
  const s = DateTime.fromISO(String(r.start), { zone: cfg.timezone });
  if (!s.isValid || s.toISODate() !== tomorrow) continue;
  out.push({ json: { ...r, when: s.toFormat("cccc, LLLL d 'at' h:mm a") } });
}
return out;
